// Reproducible offline evaluation of recommendation methods A, B and C.
//
// IMPORTANT: every number produced here comes from SIMULATED student profiles
// generated by a seeded pseudo-random process. They measure algorithm behaviour
// on synthetic data and are NOT evidence of real learning outcomes.

import type { EngineSettings, PerformanceThresholds, TopicStatus } from '@/types';
import { clamp, createRng, randInt, randNormal } from '@/lib/random';
import { prioritizedTopologicalOrder } from './graph';
import { isTopicMastered, validatePrerequisites, type EngineConfig, type TopicSignal } from './pbwps';
import { METHOD_NAMES, runMethod, type MethodId } from './baselines';

/** Curriculum metadata needed to simulate students (no performance data). */
export interface CurriculumTopic {
  id: string;
  name: string;
  subjectId: string;
  difficulty: number;
  importance: number;
  estimatedMinutes: number;
  prerequisites: string[];
  order: number;
}

export interface SimulatedProfile {
  id: string;
  ability: number;
  /** Hidden "true" mastery per topic (0–100) — the ground truth for evaluation. */
  trueMastery: Record<string, number>;
  /** Observable state given to the algorithms. */
  signals: TopicSignal[];
}

export interface ExperimentConfig {
  seed: number;
  profileCount: number;
  /** Size of the recommendation list being evaluated. */
  topK: number;
  /** True mastery below this marks a topic as genuinely weak. */
  weakThreshold: number;
  /** Simulated study budget (minutes) for the path-completion metric. */
  studyBudgetMinutes: number;
  /** Fixed reference date so runs are reproducible. */
  referenceDate: string;
}

export const DEFAULT_EXPERIMENT_CONFIG: ExperimentConfig = {
  seed: 20251101,
  profileCount: 120,
  topK: 5,
  weakThreshold: 40,
  studyBudgetMinutes: 600,
  referenceDate: '2026-01-15T12:00:00.000Z',
};

const DAY = 86_400_000;

export function generateSimulatedProfiles(curriculum: CurriculumTopic[], config: ExperimentConfig): SimulatedProfile[] {
  const rng = createRng(config.seed);
  const now = new Date(config.referenceDate).getTime();
  const byOrder = (a: CurriculumTopic, b: CurriculumTopic) => a.order - b.order;
  const { order, blocked } = prioritizedTopologicalOrder(curriculum, byOrder);
  const sequence = [...order, ...blocked];
  const byId = new Map(curriculum.map((t) => [t.id, t]));

  const profiles: SimulatedProfile[] = [];
  for (let p = 0; p < config.profileCount; p += 1) {
    const ability = clamp(randNormal(rng, 60, 16), 15, 95);
    const assessRate = 0.3 + rng() * 0.5;
    const mastery: Record<string, number> = {};
    const statuses: Record<string, TopicStatus> = {};
    const signals: TopicSignal[] = [];

    for (const id of sequence) {
      const topic = byId.get(id)!;
      const prereqs = topic.prerequisites.filter((x) => byId.has(x));
      const own = ability - (topic.difficulty - 3) * 7 + randNormal(rng, 0, 14);
      const prereqAvg = prereqs.length > 0 ? prereqs.reduce((s, x) => s + (mastery[x] ?? ability), 0) / prereqs.length : own;
      mastery[id] = Math.round(clamp(0.7 * own + 0.3 * prereqAvg, 0, 100));

      const assessed = rng() < assessRate;
      // A 5-question assessment observes mastery in 20-point steps, with noise.
      const observed = assessed ? clamp(Math.round((mastery[id] + randNormal(rng, 0, 9)) / 20) * 20, 0, 100) : null;
      const prereqsDone = prereqs.every((x) => statuses[x] === 'completed');
      let status: TopicStatus = 'not-started';
      if (observed !== null && observed >= 60 && prereqsDone && rng() < 0.6) status = 'completed';
      else if (rng() < 0.15) status = 'in-progress';
      statuses[id] = status;

      signals.push({
        ...topic,
        latestScore: observed,
        attempts: observed === null ? 0 : 1,
        lastPracticedAt: observed === null ? null : new Date(now - randInt(rng, 0, 45) * DAY).toISOString(),
        status,
      });
    }
    signals.sort((a, b) => a.order - b.order);
    profiles.push({ id: `sim-${String(p + 1).padStart(3, '0')}`, ability: Math.round(ability), trueMastery: mastery, signals });
  }
  return profiles;
}

// ---------------------------------------------------------------------------
// Metrics
// ---------------------------------------------------------------------------

export interface MetricValues {
  /** Share of genuinely weak topics surfaced in the top-K (recall@K, normalised by min(K, |weak|)). */
  weakTopicIdentification: number;
  /** nDCG@K where relevance = true knowledge gap (100 − true mastery). */
  relevance: number;
  /** Share of top-K recommendations whose prerequisites are already satisfied. */
  prerequisiteCompliance: number;
  /** Mean wall-clock time to produce ranking + sequence (ms). */
  generationTimeMs: number;
  /** Share of attempted path steps that succeed when the simulated learner follows the sequence. */
  pathCompletion: number;
}

export interface MethodSummary {
  method: MethodId;
  name: string;
  mean: MetricValues;
  sd: MetricValues;
}

export interface ExperimentResult {
  config: ExperimentConfig;
  profileCount: number;
  topicCount: number;
  averageWeakTopics: number;
  methods: MethodSummary[];
  ranAt: string;
  simulated: true;
}

export function dcg(relevances: number[]): number {
  return relevances.reduce((sum, rel, i) => sum + rel / Math.log2(i + 2), 0);
}

export function ndcgAtK(ranking: string[], relevance: Record<string, number>, candidates: string[], k: number): number {
  const actual = dcg(ranking.slice(0, k).map((id) => relevance[id] ?? 0));
  const ideal = dcg(candidates.map((id) => relevance[id] ?? 0).sort((a, b) => b - a).slice(0, k));
  return ideal === 0 ? 1 : actual / ideal;
}

/** Follows a sequence under a time budget; a step fails if its prerequisites are not yet mastered. */
export function simulatePathCompletion(
  sequence: string[],
  signals: TopicSignal[],
  masteryScore: number,
  budgetMinutes: number,
): number {
  const byId = new Map(signals.map((s) => [s.id, s]));
  const done = new Set(signals.filter((s) => isTopicMastered(s, masteryScore)).map((s) => s.id));
  let budget = budgetMinutes;
  let attempted = 0;
  let succeeded = 0;
  for (const id of sequence) {
    if (budget <= 0) break;
    const topic = byId.get(id);
    if (!topic || done.has(id)) continue;
    attempted += 1;
    const ready = topic.prerequisites.every((p) => !byId.has(p) || done.has(p));
    if (ready) {
      succeeded += 1;
      done.add(id);
      budget -= topic.estimatedMinutes;
    } else {
      budget -= 30; // time lost discovering missing background knowledge
    }
  }
  return attempted === 0 ? 1 : succeeded / attempted;
}

function mean(values: number[]): number {
  return values.length === 0 ? 0 : values.reduce((a, b) => a + b, 0) / values.length;
}

function sd(values: number[]): number {
  if (values.length < 2) return 0;
  const m = mean(values);
  return Math.sqrt(values.reduce((s, v) => s + (v - m) ** 2, 0) / (values.length - 1));
}

const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

export function evaluateProfile(
  profile: SimulatedProfile,
  method: MethodId,
  engine: EngineConfig,
  config: ExperimentConfig,
): Partial<MetricValues> & { generationTimeMs: number } {
  const start = now();
  const output = runMethod(method, profile.signals, engine);
  const generationTimeMs = now() - start;

  const byId = new Map(profile.signals.map((s) => [s.id, s]));
  const incomplete = profile.signals.filter((s) => s.status !== 'completed').map((s) => s.id);
  const weak = incomplete.filter((id) => profile.trueMastery[id] < config.weakThreshold);
  const topK = output.ranking.slice(0, config.topK);
  const relevance = Object.fromEntries(incomplete.map((id) => [id, (100 - profile.trueMastery[id]) / 100]));

  const result: Partial<MetricValues> & { generationTimeMs: number } = {
    generationTimeMs,
    relevance: ndcgAtK(topK, relevance, incomplete, config.topK),
    pathCompletion: simulatePathCompletion(output.sequence, profile.signals, engine.prerequisiteMastery, config.studyBudgetMinutes),
  };
  if (weak.length > 0) {
    const hits = topK.filter((id) => weak.includes(id)).length;
    result.weakTopicIdentification = hits / Math.min(config.topK, weak.length);
  }
  if (topK.length > 0) {
    const compliant = topK.filter((id) => validatePrerequisites(byId.get(id)!, byId, engine.prerequisiteMastery).satisfied).length;
    result.prerequisiteCompliance = compliant / topK.length;
  }
  return result;
}

export function runExperiment(
  curriculum: CurriculumTopic[],
  engineSettings: EngineSettings,
  thresholds: PerformanceThresholds,
  config: ExperimentConfig = DEFAULT_EXPERIMENT_CONFIG,
): ExperimentResult {
  const profiles = generateSimulatedProfiles(curriculum, config);
  const engine: EngineConfig = { ...engineSettings, thresholds, now: new Date(config.referenceDate) };
  const keys: (keyof MetricValues)[] = ['weakTopicIdentification', 'relevance', 'prerequisiteCompliance', 'generationTimeMs', 'pathCompletion'];

  const methods = (['A', 'B', 'C'] as MethodId[]).map((method) => {
    const samples: Record<keyof MetricValues, number[]> = {
      weakTopicIdentification: [],
      relevance: [],
      prerequisiteCompliance: [],
      generationTimeMs: [],
      pathCompletion: [],
    };
    for (const profile of profiles) {
      const r = evaluateProfile(profile, method, engine, config);
      for (const k of keys) if (r[k] !== undefined) samples[k].push(r[k]!);
    }
    const m = {} as MetricValues;
    const s = {} as MetricValues;
    for (const k of keys) {
      m[k] = mean(samples[k]);
      s[k] = sd(samples[k]);
    }
    return { method, name: METHOD_NAMES[method], mean: m, sd: s };
  });

  const averageWeakTopics = mean(
    profiles.map(
      (p) => p.signals.filter((s) => s.status !== 'completed' && p.trueMastery[s.id] < config.weakThreshold).length,
    ),
  );

  return {
    config,
    profileCount: profiles.length,
    topicCount: curriculum.length,
    averageWeakTopics,
    methods,
    ranAt: new Date().toISOString(),
    simulated: true,
  };
}
